-- 0033_subjects_in_postgres.sql
--
-- The syllabus catalog moves out of the browser.
--
-- Admin -> Subject master has always been editable, but it wrote to
-- `v6_subjects` in localStorage: the admin's own browser and nowhere else.
-- Students never saw an edit, mentors never saw it, and it was gone on a
-- different device or a cleared cache. A setting that looks configurable and
-- reaches nobody is worse than one that is plainly hardcoded, because nobody
-- finds out until the syllabus disagrees with itself.
--
-- Shape follows plan_templates: one row per subject with its topics as jsonb,
-- rather than a normalised topics table. The app reads and writes the catalog
-- as a whole -- eleven rows, never queried by topic -- so a second table would
-- buy joins nobody performs.
--
-- sort_order is explicit. The catalog's ORDER is meaningful: it drives display
-- and, through the plan templates, the sequence microthemes are taught in.
-- Row order in Postgres is not a promise, so it is stored rather than implied.
--
-- Seeded from src/data/syllabus.ts so the two cannot disagree on day one. The
-- bundled copy stays as the fallback for local demo mode, which has no
-- database to read from.
--
-- Non-ASCII (the emoji icons, the en-dash in "18th-19th Century") is written as
-- JSON \uXXXX escapes so this file stays pure ASCII and cannot be corrupted in
-- transit. jsonb decodes them on the way in.
-- ---------------------------------------------------------------------------

create table if not exists public.subjects (
  id                 text primary key,
  name               text not null,
  icon               text not null default '',
  color              text not null default 'slate',
  stage              text not null default 'prelims'
                     check (stage in ('prelims', 'mains')),
  rajasthan_specific boolean not null default false,
  archived           boolean not null default false,
  -- Display and teaching order. See the note above.
  sort_order         int not null default 0,
  topics             jsonb not null default '[]'::jsonb,
  updated_at         timestamptz not null default now(),
  constraint subjects_topics_is_array check (jsonb_typeof(topics) = 'array')
);

comment on table public.subjects is
  'The syllabus catalog. One row per subject; topics held as jsonb. Admin-writable, readable by anyone signed in.';

create index if not exists subjects_order_idx on public.subjects (archived, sort_order);

alter table public.subjects enable row level security;

-- Everyone signed in reads the catalog: students need it to see their plan,
-- mentors to review it. Nothing here is content -- it is the table of contents.
drop policy if exists "read subjects" on public.subjects;
create policy "read subjects"
  on public.subjects for select
  using (auth.uid() is not null);

drop policy if exists "admins write subjects" on public.subjects;
create policy "admins write subjects"
  on public.subjects for all
  using (public.current_role_of(auth.uid()) = 'admin')
  with check (public.current_role_of(auth.uid()) = 'admin');

-- Deliberate, not inherited. Supabase's default privileges hand `authenticated`
-- everything on a new table (the trap 0028 had to undo), so the grants are
-- stated outright: reads for anyone signed in, writes gated by the policy
-- above, and nothing at all for anon.
revoke all on public.subjects from anon;
revoke all on public.subjects from authenticated;
grant select, insert, update, delete on public.subjects to authenticated;

-- ---------------------------------------------------------------------------
-- Seed, from the shipped syllabus. on conflict do nothing: if this has already
-- run and an admin has since edited the catalog, their edits stand.
-- ---------------------------------------------------------------------------

-- CORRECTION (applied before this file was ever run): the icon column was
-- originally written as a plain literal, '\ud83d\udcda'. With Postgres's
-- default standard_conforming_strings, that stores eighteen literal characters
-- rather than an emoji -- and because the app overwrites its local catalog from
-- this table, every subject icon in the UI would have become visible gibberish.
-- The icons now go through a jsonb round-trip, ('"..."'::jsonb #>> '{}'), which
-- makes the JSON parser decode the escapes (surrogate pairs included) while
-- keeping this file pure ASCII.
--
