-- Sanity: the catalog landed whole. 11 subjects, 243 microthemes, matching what
-- the bundle ships and what the 80-day plan is built on.
do $$
declare n_sub int; n_top int;
begin
  select count(*), coalesce(sum(jsonb_array_length(topics)), 0)
    into n_sub, n_top from public.subjects;
  if n_sub <> 11 or n_top <> 243 then
    raise exception 'catalog is % subjects / % microthemes, expected 11 / 243', n_sub, n_top;
  end if;
end $$;
